constexpr std::array<const char*, 11> Names{
    "v_ldexp_f16", "v_frexp_mant_f16", "v_frexp_exp_i16_f16", "v_cvt_norm_i16_f16", "v_cvt_norm_u16_f16", "v_cvt_pknorm_i16_f16",
    "v_cvt_pknorm_u16_f16", "v_cmp_class_f16", "v_sat_pk_u8_i16", "v_mul_legacy_f32", "v_mac_legacy_f32",
};

std::array<std::uint32_t, 4> BufferDescriptor(const void* data, std::uint32_t count) {
    const auto address = reinterpret_cast<std::uintptr_t>(data);
    return {static_cast<std::uint32_t>(address), static_cast<std::uint32_t>((address >> 32u) & 0xffffu) | (4u << 16u), count, 0x11016facu};
}

std::string Hex(std::uint32_t value) {
    char text[16];
    std::snprintf(text, sizeof(text), "0x%08x", value);
    return text;
}

bool IsNan32(std::uint32_t bits) {
    return (bits & 0x7fffffffu) > 0x7f800000u;
}

bool IsNan16(std::uint32_t bits) {
    return (bits & 0x7fffu) > 0x7c00u;
}

bool IsDenormal32(std::uint32_t bits) {
    return (bits & 0x7f800000u) == 0u && (bits & 0x007fffffu) != 0u;
}

bool Matches(std::uint32_t column, std::uint32_t actual, std::uint32_t expected) {
    if (actual == expected) return true;
    if (column <= 1u) return (actual >> 16u) == (expected >> 16u) && IsNan16(actual) && IsNan16(expected);
    return column >= 9u && IsNan32(actual) && IsNan32(expected);
}

void Run(AgcDriver::VulkanDevice& device, std::uint32_t first, std::uint32_t count) {
    Input.fill(0u);
    for (std::uint32_t lane = 0; lane < count; ++lane) {
        const auto& vector = Vectors[first + lane];
        Input[lane * Inputs] = vector.a;
        Input[lane * Inputs + 1] = vector.b;
        Input[lane * Inputs + 2] = vector.c;
    }
    Output.fill(0xdeadbeefu);
    std::vector<std::uint32_t> userData(8, 0u);
    const auto input = BufferDescriptor(Input.data(), static_cast<std::uint32_t>(Input.size()));
    const auto output = BufferDescriptor(Output.data(), static_cast<std::uint32_t>(Output.size()));
    std::copy(input.begin(), input.end(), userData.begin());
    std::copy(output.begin(), output.end(), userData.begin() + 4);
    const std::span<const std::uint32_t> code(MiscCode);
    const std::array<ShaderRecompiler::MemoryRegion, 1> memory{{{reinterpret_cast<std::uintptr_t>(code.data()), std::as_bytes(code)}}};
    const ShaderRecompiler::ShaderComputeStageInfo compute{{Threads, 1, 1}, 0, {false, false, false}, false, 1};
    ShaderRecompiler::RecompileRequest request{
        {ShaderStage::Compute, reinterpret_cast<std::uintptr_t>(code.data()), code, 0, {}},
        {32, 0, userData, compute, std::nullopt, std::nullopt, memory},
        device.Target(),
        {0, 0, 0, 128}
    };
    request.useCache = false;
    const auto result = ShaderRecompiler::Recompile(request);
    device.Dispatch(result, 1, 1, 1, {}, reinterpret_cast<std::uintptr_t>(code.data()));
    device.WaitIdle();
}

void Check(std::uint32_t first, std::uint32_t count) {
    for (std::uint32_t lane = 0; lane < count; ++lane) {
        const auto& vector = Vectors[first + lane];
        const bool denormal = IsDenormal32(vector.a) || IsDenormal32(vector.b) || IsDenormal32(vector.expected[9]);
        for (std::uint32_t column = 0; column < Names.size(); ++column) {
            if (column >= 9u && denormal) continue;
            const auto expected = vector.expected[column];
            const auto actual = Output[lane * Results + column];
            Require(Matches(column, actual, expected), std::string("f16 misc: vector ") + std::to_string(first + lane) + " (" + Hex(vector.a) + ", " + Hex(vector.b) + ", " + Hex(vector.c) + ") " + Names[column] + " is " + Hex(actual) + ", expected " + Hex(expected));
        }
    }
}

const Testing::Case vectors{"Float16Misc_HalfPrecisionAndLegacyOps_MatchReferenceVectors", [] {
    auto& device = SharedVulkanTestDevice();
    constexpr std::uint32_t total = sizeof(Vectors) / sizeof(Vectors[0]);
    for (std::uint32_t first = 0; first < total; first += Threads) {
        const auto count = std::min(Threads, total - first);
        Run(device, first, count);
        Check(first, count);
    }
}};

